{
  "record_id": "batch.motif.siberian-koryak-texts-bogoras-archive-l3019-l3219",
  "source_text_path": "texts/public-domain/siberian/project-gutenberg/koryak-texts-bogoras.md",
  "passage_locator": {
    "label": "VOWELS. / I                  E / CONSONANTS. / OPEN    COUNTRY.; lines 3019-3219",
    "start": "3019",
    "end": "3219",
    "translation": "Koryak Texts",
    "notes": "Stable markdown line range generated from canonical text."
  },
  "canonical_text": {
    "quote": "",
    "summary": "The passage concludes a prior episode in which Eme'mqut's woman visits some fishermen, tramples someone, scatters fly-eggs or bumblebees around herself, and these bumblebees become fishermen or vice versa, after which Eme'mqut simply goes home. A new episode then begins: Eme'mqut and his people live together, hunt whales, kill one, and bring it home. They organize a thanksgiving ceremonial, gathering reindeer-breeding people and Magpie-Women. During the whale festival, various animal-person women (Magpie-Woman, Fox-Woman, another Fox-Woman, Small-Magpie-Woman) are called to dance and sing. Magpie-Woman sings about instructions from her mother and grandmother regarding leaving or not leaving items in other people's wallets, implying habitual pilfering; Kilu' agrees their wallets are found half eaten, and Magpie-Woman feels ashamed and flies away. Fox-Woman sings about her brother Pilferer making a knife with an ornamented handle to strap to her thigh so she can eat whale-skin, but she has forgotten it. Old man Big-Raven remarks that they are singing about feeding at other people's expense. Another Fox-Woman sings that she eats hard excrements and gnaws snowshoe-strings; Eme'mqut notes that when they find them, the snowshoe-strings are gnawed through, and she feels ashamed and leaves. Small-Magpie-Woman, called to dance, says she is ashamed and sings about a magpie striding and running on the gables of other people's storehouses. An editorial footnote compares this whale festival episode with a parallel text in W. Jochelson's \"The Koryak.\"",
    "language": "English",
    "quote_policy": "summarized"
  },
  "literal_observations": [
    {
      "id": "obs:1",
      "text": "Eme'mqut's woman visits some fishermen by way of Kilu'.",
      "category": "action",
      "evidence_refs": ["ev:1"]
    },
    {
      "id": "obs:2",
      "text": "Eme'mqut's woman tramples someone and scatters fly-eggs or bumblebees around herself.",
      "category": "action",
      "evidence_refs": ["ev:1"]
    },
    {
      "id": "obs:3",
      "text": "The bumblebees become fishermen, or fishermen become bumblebees, as a result of the action.",
      "category": "sequence",
      "evidence_refs": ["ev:1"]
    },
    {
      "id": "obs:4",
      "text": "Eme'mqut, having nothing more to do, goes home.",
      "category": "action",
      "evidence_refs": ["ev:1"]
    },
    {
      "id": "obs:5",
      "text": "Eme'mqut and his people are living together.",
      "category": "setting",
      "evidence_refs": ["ev:2"]
    },
    {
      "id": "obs:6",
      "text": "They hunt whales and kill one whale.",
      "category": "action",
      "evidence_refs": ["ev:2"]
    },
    {
      "id": "obs:7",
      "text": "They take the killed whale home.",
      "category": "action",
      "evidence_refs": ["ev:2"]
    },
    {
      "id": "obs:8",
      "text": "After killing the whale, they arrange a thanksgiving ceremonial.",
      "category": "action",
      "evidence_refs": ["ev:2"]
    },
    {
      "id": "obs:9",
      "text": "They gather all the reindeer-breeding people and the Magpies (Magpie-Women) for the ceremonial.",
      "category": "action",
      "evidence_refs": ["ev:2"]
    },
    {
      "id": "obs:10",
      "text": "Someone calls to Magpie-Woman, telling her it is her turn to dance.",
      "category": "speech",
      "evidence_refs": ["ev:3"]
    },
    {
      "id": "obs:11",
      "text": "Magpie-Woman replies that she is unskilful and uses the refrain \"Vakikikikikiki\" while speaking.",
      "category": "speech",
      "evidence_refs": ["ev:3"]
    },
    {
      "id": "obs:12",
      "text": "Magpie-Woman says her mother told her not to leave anything from other people's wallets.",
      "category": "speech",
      "evidence_refs": ["ev:3"]
    },
    {
      "id": "obs:13",
      "text": "Magpie-Woman says her grandmother told her to leave something from other people's wallets.",
      "category": "speech",
      "evidence_refs": ["ev:3"]
    },
    {
      "id": "obs:14",
      "text": "Kilu' responds that when they come to find the wallets, the wallets are eaten or half eaten.",
      "category": "speech",
      "evidence_refs": ["ev:4"]
    },
    {
      "id": "obs:15",
      "text": "Magpie-Woman has nothing to say, feels ashamed, and flies away.",
      "category": "sequence",
      "evidence_refs": ["ev:4"]
    },
    {
      "id": "obs:16",
      "text": "Fox-Woman is called to dance and begins to grow excited.",
      "category": "sequence",
      "evidence_refs": ["ev:5"]
    },
    {
      "id": "obs:17",
      "text": "Fox-Woman sings that her brother Pilferer made a knife with a well-ornamented handle and wanted to strap it to her thigh.",
      "category": "speech",
      "evidence_refs": ["ev:5"]
    },
    {
      "id": "obs:18",
      "text": "Fox-Woman says she has forgotten the knife and wonders with what she will eat the whale-skin.",
